const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const seed={jobs:[{id:1,title:'CNC Machine Operator',location:'Shah Alam, Selangor',salary:2800,max:3800,shift:'Day shift',skills:['CNC operation','Quality control'],openings:4},{id:2,title:'Warehouse Associate',location:'Senai, Johor',salary:2000,max:2800,shift:'Rotating shift',skills:['Forklift','Inventory'],openings:8},{id:3,title:'Maintenance Technician',location:'Bayan Lepas, Penang',salary:3000,max:4200,shift:'Day shift',skills:['Electrical','Maintenance'],openings:2}],people:[{id:1,name:'Ahmad Farhan',location:'Shah Alam, Selangor',skills:['CNC operation','Quality control'],shift:'Day shift',available:'Immediately',experience:4,consent:true},{id:2,name:'Siti Nur Aisyah',location:'Klang, Selangor',skills:['CNC operation','Quality control','Inventory'],shift:'Day shift',available:'In 2 weeks',experience:3,consent:true},{id:3,name:'Raj Kumar',location:'Shah Alam, Selangor',skills:['Quality control','Maintenance'],shift:'Day shift',available:'Immediately',experience:5,consent:true},{id:4,name:'Lim Wei Jian',location:'Bayan Lepas, Penang',skills:['Electrical','Maintenance'],shift:'Day shift',available:'Immediately',experience:6,consent:true},{id:5,name:'Nur Amirah',location:'Senai, Johor',skills:['Forklift','Inventory'],shift:'Rotating shift',available:'In 2 weeks',experience:2,consent:true}],shortlist:[],interviews:[],company:'Acme Manufacturing',worker:null};
let state;try{state=JSON.parse(localStorage.getItem('iwo-v1'))||structuredClone(seed)}catch{state=structuredClone(seed)}let role='employer',view='overview',query='',region='',selectedJob=1;const persist=()=>localStorage.setItem('iwo-v1',JSON.stringify(state));const money=n=>'RM '+Number(n).toLocaleString('en-MY');const initials=n=>n.split(' ').slice(0,2).map(v=>v[0]).join('');
function score(p,j){return Math.round(70*j.skills.filter(s=>p.skills.includes(s)).length/j.skills.length+20*(p.shift===j.shift)+10*(p.location===j.location))}function ranked(){let j=state.jobs.find(j=>j.id===Number(selectedJob))||state.jobs[0];return state.people.filter(p=>p.consent).map(p=>({...p,score:score(p,j)})).sort((a,b)=>b.score-a.score)}
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',3500)}
const navs=[['overview','◫','Overview'],['jobs','▣','Jobs'],['talent','♧','Talent matches'],['shortlist','☆','Shortlist'],['interviews','▦','Interviews'],['settings','⚙','Workspace settings']];
function pageTop(title,sub,action,label){return `<div class="pagetop"><div><div class="eyebrow">YOUR WORKFORCE, CONNECTED</div><h1>${title}</h1><p>${sub}</p></div>${action?`<button class="primary" data-action="${action}">＋ ${label}</button>`:''}</div>`}function panel(title,sub,body,link=''){return `<section class="panel"><div class="panelhead"><div><h2>${title}</h2>${sub?`<p>${sub}</p>`:''}</div>${link}</div>${body}</section>`}
function jobrow(j){return `<div class="job"><div class="jobicon">${j.id===2?'▤':'⚒'}</div><div class="jobinfo"><h3>${esc(j.title)}</h3><div class="meta">⌖ ${esc(j.location)} &nbsp; · &nbsp; ${esc(j.shift)}</div><div class="tags">${j.skills.map(s=>`<span class="tag">${esc(s)}</span>`).join('')}<span class="tag">${j.openings} openings</span></div><button class="link" data-action="match" data-id="${j.id}">${role==='worker'?'Check my fit':'View matches'} →</button></div><div class="jobright"><span class="badge">● Active</span><strong>${money(j.salary)}–${Number(j.max).toLocaleString()}</strong><small>per month</small></div></div>`}
function candidate(p,compact=false){return compact?`<div class="candidate"><div class="face">${initials(p.name)}</div><div><h3>${esc(p.name)}</h3><p>${esc(p.skills[0])} · ${p.experience} yrs</p></div><div class="match">${p.score}%<small>skill fit</small></div></div>`:`<article class="panel person"><span class="match">${p.score}%<small>match score</small></span><div class="face">${initials(p.name)}</div><h2>${esc(p.name)}</h2><p>⌖ ${esc(p.location)}<br>${p.experience} years experience · ${esc(p.shift)}<br><span class="badge">● ${esc(p.available)}</span></p><div class="tags">${p.skills.map(s=>`<span class="tag">${esc(s)}</span>`).join('')}</div><p>Fit: ${state.jobs.find(j=>j.id===Number(selectedJob))?.skills.filter(s=>p.skills.includes(s)).length||0} required skills · ${p.score===100?'location and shift aligned':'review location and shift'}</p><div class="rowactions"><button class="primary" data-action="shortlist" data-id="${p.id}">${state.shortlist.includes(p.id)?'✓ Shortlisted':'+ Shortlist'}</button><button data-action="schedule" data-id="${p.id}">Interview</button><button aria-label="Prepare WhatsApp message" data-action="message" data-id="${p.id}">↗</button></div></article>`}
function overview(){let j=state.jobs.find(j=>j.id==selectedJob)||state.jobs[0], matches=ranked().slice(0,3);return `<div class="kg-intro"><span>THE NEW WAY TO GET TO WORK.</span><span>01 / MALAYSIA FIRST ↗</span></div><section class="kg-stage"><div class="kg-copy"><div class="kg-live"><i></i> BUILT FOR MALAYSIA’S DOERS</div><h1>Real skills.<br>Real work.<br><em>Let’s go.</em></h1><p>The right people. The right shift. One straight line from “we’re hiring” to “see you Monday”.</p><div class="kg-ctas"><button data-action="talent">Cari pekerja <span>↗</span></button><button data-action="workerhome">Cari kerja <span>↗</span></button></div><div class="kg-note">FREE TO START &nbsp; / &nbsp; SKILLS BEFORE CVs</div></div><div class="kg-machine"><div class="machine-label"><span>KERJAGO / MATCH ENGINE</span><span class="demo-dot">INTERACTIVE DEMO</span></div><div class="machine-job"><span class="stepnum">01</span><div><small>CHOOSE THE WORK</small><select id="jobfilter" aria-label="Match against job">${state.jobs.map(x=>`<option value="${x.id}" ${x.id==selectedJob?'selected':''}>${esc(x.title)}</option>`).join('')}</select><p>${esc(j.location)} · ${esc(j.shift)}</p></div><span class="job-arrow">↙</span></div><div class="skill-wire">${j.skills.map(x=>`<span>✓ ${esc(x)}</span>`).join('')}</div><div class="match-line"><span>02 / YOUR PEOPLE, FOUND.</span><span>SKILLS + SHIFT + LOCATION ↓</span></div><div class="engine-people">${matches.map((p,i)=>`<div class="engine-person" style="--delay:${i*100}ms"><div class="engine-initial">${initials(p.name)}</div><div><strong>${esc(p.name)}</strong><small>${esc(p.available)} · ${p.experience} years</small></div><b>${p.score}<small>% FIT</small></b><button data-action="shortlist" data-id="${p.id}" aria-label="Shortlist ${esc(p.name)}">${state.shortlist.includes(p.id)?'✓':'+'}</button></div>`).join('')}</div><div class="engine-foot"><span>03 / MAKE YOUR MOVE</span><button data-action="talent">Build your shortlist ↗</button></div></div></section><div class="kg-ticker"><span>MANUFACTURING</span><b>✳</b><span>LOGISTICS</span><b>✳</b><span>TECHNICAL TRADES</span><b>✳</b><span>OPERATIONS</span><b>✳</b><span>YOUR NEXT MOVE</span><b>↗</b></div><section class="kg-bottom"><div class="kg-section-title"><small>THE WORK STARTS HERE</small><h2>Open shifts.<br>New possibilities.</h2><button class="link" data-action="jobs">Explore all ${state.jobs.length} roles ↗</button></div><div class="kg-jobgrid">${state.jobs.slice(0,3).map((j,i)=>`<article class="kg-job"><div class="kg-job-top"><span>0${i+1} / ${esc(j.shift).toUpperCase()}</span><span>↗</span></div><h3>${esc(j.title)}</h3><p>⌖ ${esc(j.location)}</p><strong>${money(j.salary)}–${Number(j.max).toLocaleString()}</strong><small>PER MONTH</small><div class="tags">${j.skills.map(x=>`<span class="tag">${esc(x)}</span>`).join('')}</div><button data-action="match" data-id="${j.id}">Meet the matches <span>→</span></button></article>`).join('')}</div></section><div class="kg-ledger"><span><b>${state.jobs.length}</b> ACTIVE ROLES</span><span><b>${state.people.filter(p=>p.consent).length}</b> DEMO PROFILES</span><span><b>${state.shortlist.length}</b> ON YOUR SHORTLIST</span><span><b>${state.interviews.length}</b> CONVERSATIONS PLANNED</span></div>`}
function interviewMini(i){return `<div class="timecard"><span class="badge">Scheduled · MYT</span><h3>${esc(state.people.find(p=>p.id===i.person)?.name||'Candidate')}</h3><p>${esc(i.date)} · ${esc(i.time)} · ${esc(i.mode)}</p><button data-action="interviews">View interview →</button></div>`}
function talent(short=false){let people=ranked().filter(p=>(!short||state.shortlist.includes(p.id))&&(!query||[p.name,p.location,...p.skills].join(' ').toLowerCase().includes(query.toLowerCase()))&&(!region||p.location.includes(region)));return pageTop(short?'Your shortlist':'Good people. The right fit.',short?'A focused list. A faster path to your next hire.':'Every match explained by skills, shift, and location.')+`<div class="toolbar"><input id="search" aria-label="Search talent" placeholder="Search skills, names, or locations" value="${esc(query)}"><select id="jobfilter" aria-label="Match against job">${state.jobs.map(j=>`<option value="${j.id}" ${j.id==selectedJob?'selected':''}>${esc(j.title)}</option>`).join('')}</select><select id="region" aria-label="Filter state"><option value="">All locations</option>${['Selangor','Johor','Penang'].map(r=>`<option ${r===region?'selected':''}>${r}</option>`).join('')}</select></div><div class="notice">Explainable matching: skills 70% + shift 20% + exact location 10%. Scores express profile fit, not a hiring recommendation.</div><div class="cards">${people.map(p=>candidate(p)).join('')||'<div class="panel empty">No candidates here yet. Explore your talent matches.</div>'}</div>`}
function jobs(){return pageTop(role==='worker'?'Find your next good shift.':'Jobs that move your business.','Clear pay. Clear shifts. Real skills.','post','Post a job')+panel('Open opportunities',`${state.jobs.length} active roles in Malaysia`,state.jobs.map(jobrow).join(''))}
function interviews(){return pageTop('A conversation changes everything.','Plan interviews in Malaysia time (MYT, UTC+8).')+panel('Interview schedule','Times are saved locally. Confirm with your candidate before attending.',state.interviews.length?state.interviews.map(i=>interviewMini(i)).join(''):'<div class="empty">Your calendar is clear. Shortlist talent and schedule your first interview.</div>')}
function worker(){let p=state.worker;return pageTop(p?`Welcome, ${esc(p.name.split(' ')[0])}.`:'Your skills open doors.','Build a work profile in minutes. Find a shift that fits your life.','register',p?'Edit my profile':'Create worker profile')+`<section class="hero"><div><div class="eyebrow">MADE FOR PEOPLE WHO DO</div><h2>Less paperwork.<br>More possibility.</h2><p>Share what you can do, where you want to work, and when you can start. You control whether employers can find you.</p><button data-action="register">${p?'Manage my skills & privacy':'Get started · It’s free'} ↗</button></div><div class="hero-side"><strong>${state.jobs.length}</strong><p>open roles in this demo</p></div></section>`+(p?`<div class="notice">Profile visibility: ${p.consent?'Discoverable by demo employers':'Private — hidden from employer matches'}. No phone number is collected in this prototype.</div>`:'')+panel('Find your next opportunity','Transparent monthly salary. Skills before CVs.',state.jobs.map(jobrow).join(''))}
function settings(){return pageTop('Your workspace. Your rules.','Simple controls for your team and your data.')+panel('Company profile','Demo settings are local to this browser.',`<div class="timecard"><h3>${esc(state.company)}</h3><p>Free basic recruitment · Malaysia · Manufacturing</p><button data-action="company">Edit employer account</button><button data-action="upgrade">Explore paid automation</button></div>`)+panel('Privacy & data','Use fictional details while exploring this prototype.',`<div class="timecard"><p>Export your local workspace, remove a worker profile, or reset all demo data.</p><button data-action="export">Export workspace JSON</button><button data-action="deleteprofile">Delete my worker profile</button><button data-action="reset">Reset demo workspace</button></div>`)}
function admin(){return pageTop('Platform health, at a glance.','Admin preview · role selection is a demo control, not access enforcement.')+`<div class="notice">Production admin access requires server-enforced roles and audit logging. No real accounts or moderation actions are connected.</div>`+panel('Workspace overview','Local demo records only.',`<div class="timecard"><h3>${state.people.length} worker profiles · ${state.jobs.length} jobs · 1 employer</h3><p>${state.people.filter(p=>p.consent).length} discoverable profiles · ${state.interviews.length} interviews</p></div>`)+panel('Job moderation queue','Review the information employers publish.',state.jobs.map(j=>`<div class="job"><div class="jobinfo"><h3>${esc(j.title)}</h3><div class="meta">${esc(j.location)} · ${money(j.salary)}–${money(j.max)}</div></div><button data-action="removejob" data-id="${j.id}">Remove demo job</button></div>`).join(''))}
function render(){let current=navs.find(n=>n[0]===view);$('#crumb').textContent=role==='admin'?'Admin dashboard':role==='worker'?'Worker workspace':current?.[2]||'Overview';$('#nav').innerHTML=navs.map(n=>`<a href="#${n[0]}" class="${view===n[0]?'active':''}" aria-label="${n[2]}"><i>${n[1]}</i><span>${n[2]}</span>${n[0]==='shortlist'?`<em>${state.shortlist.length}</em>`:''}</a>`).join('');$('#main').innerHTML=role==='admin'?admin():role==='worker'&&view==='overview'?worker():({overview,jobs,talent,shortlist:()=>talent(true),interviews,settings}[view]||overview)();document.querySelector('.workspace span').innerHTML=esc(state.company)+'<small>Employer workspace · Malaysia</small>';}
function show(title,body){$('#modalcontent').innerHTML=`<button class="close" aria-label="Close dialog">✕</button><h2>${title}</h2>${body}`;$('#modal').showModal();$('.close').onclick=()=>$('#modal').close()}const field=(name,label,type='text',value='',extra='')=>`<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" required ${extra}></label>`;const actions=label=>`<div class="formactions"><button type="button" data-action="close">Cancel</button><button class="primary" type="submit">${label}</button></div>`;
function form(title,html,save){show(title,`<form>${html}</form>`);$('#modal form').onsubmit=e=>{e.preventDefault();try{save(Object.fromEntries(new FormData(e.target)));persist();$('#modal').close();render()}catch(err){toast(err.message)}}}
function act(a,id){if(a==='workerhome'){role='worker';$('#role').value='worker';view='overview';render();return}const p=state.people.find(p=>p.id===Number(id));if(['talent','jobs','interviews'].includes(a)){location.hash=a;return}if(a==='close')return $('#modal').close();if(a==='post'){if(role!=='employer')return toast('Switch to Employer view to post a job.');form('Find your next great hire.',field('title','Job title')+field('location','City, state','text','Shah Alam, Selangor')+field('salary','Minimum monthly salary (RM)','number',2000,'min="1"')+field('max','Maximum monthly salary (RM)','number',3000,'min="1"')+field('openings','Number of openings','number',1,'min="1" max="500"')+'<label>Shift<select name="shift"><option>Day shift</option><option>Night shift</option><option>Rotating shift</option></select></label>'+field('skills','Required skills, separated by commas')+actions('Publish demo job'),d=>{if(+d.max<+d.salary)throw Error('Maximum salary must be at least the minimum.');state.jobs.unshift({...d,id:Date.now(),salary:+d.salary,max:+d.max,openings:+d.openings,skills:d.skills.split(',').map(s=>s.trim()).filter(Boolean)});toast('Job published to your demo workspace.');});return}if(a==='match'){selectedJob=+id;if(role==='worker'){if(!state.worker)return act('register');let j=state.jobs.find(j=>j.id===+id);show('Your fit for this role',`<p><strong>${esc(j.title)}</strong></p><h2>${score(state.worker,j)}% profile fit</h2><p>Required skills: ${j.skills.map(esc).join(', ')}<br>Your skills: ${state.worker.skills.map(esc).join(', ')}<br>Shift: ${esc(j.shift)} · ${esc(j.location)}</p><p>Application submission will be available after authenticated accounts are connected.</p>`);return}location.hash='talent';render();return}if(a==='shortlist'){if(role!=='employer')return toast('Employer view is required.');state.shortlist=state.shortlist.includes(+id)?state.shortlist.filter(v=>v!==+id):[...state.shortlist,+id];persist();render();return}if(a==='schedule'){if(role!=='employer')return toast('Employer view is required.');form('Make time for a hello.',`<p>Schedule a conversation with ${esc(p.name)}.</p>`+field('date','Interview date (MYT)','date','','min="2026-10-28"')+field('time','Time (MYT)','time')+'<label>Format<select name="mode"><option>Phone interview</option><option>Video call</option><option>On-site interview</option></select></label>'+field('notes','Meeting details or location')+actions('Schedule interview'),d=>{state.interviews.push({...d,id:Date.now(),person:+id});toast('Interview saved locally. Share the details with your candidate.');});return}if(a==='message'){show('A warmer first hello.',`<p>This draft contains only the candidate’s first name and your company. Confirm consent and the recipient in WhatsApp before sending.</p><label>Message<textarea id="draft" rows="6">${esc(`Hi ${p.name.split(' ')[0]}, this is ${state.company}. We saw your skills profile and would like to discuss an opportunity. Would you be available for a short conversation?`)}</textarea></label><div class="formactions"><button data-action="copy">Copy draft</button><button class="primary" data-action="whatsapp">Open WhatsApp ↗</button></div>`);return}if(a==='copy'){navigator.clipboard.writeText($('#draft').value).then(()=>toast('Draft copied.')).catch(()=>toast('Select and copy the draft manually.'));return}if(a==='whatsapp'){window.open('https://wa.me/?text='+encodeURIComponent($('#draft').value),'_blank','noopener,noreferrer');return}if(a==='register'){let w=state.worker||{};form('Your skills. Your next step.', '<p>Demo registration — use fictional information. No login account is created.</p>'+field('name','Name','text',w.name||'')+field('location','City, state','text',w.location||'Shah Alam, Selangor')+field('skills','Skills, separated by commas','text',w.skills?.join(', ')||'CNC operation, Quality control')+field('experience','Years of experience','number',w.experience||0,'min="0" max="60"')+'<label>Preferred shift<select name="shift">'+['Day shift','Night shift','Rotating shift'].map(v=>`<option ${v===w.shift?'selected':''}>${v}</option>`).join('')+'</select></label><label>Availability<select name="available"><option>Immediately</option><option '+(w.available==='In 2 weeks'?'selected':'')+'>In 2 weeks</option></select></label><label class="check"><input type="checkbox" name="consent" '+(w.consent?'checked':'')+'>Allow my demo profile to appear in employer matches. I can withdraw this at any time.</label>'+actions('Save worker profile'),d=>{state.worker={...d,id:w.id||Date.now(),experience:+d.experience,skills:d.skills.split(',').map(s=>s.trim()).filter(Boolean),consent:d.consent==='on'};state.people=state.people.filter(p=>p.id!==w.id);state.people.push(state.worker);toast('Profile saved. You control your visibility.');});return}if(a==='company'){form('Your employer workspace.', '<p>Demo employer profile. Verification and team login are planned for the production increment.</p>'+field('name','Company name','text',state.company)+actions('Save company'),d=>{state.company=d.name;toast('Employer profile saved.');});return}if(a==='upgrade'){show('More hiring. Less admin.',`<span class="badge">EMPLOYER PLUS · COMING NEXT</span><h2>Keep basic recruitment free.</h2><p>Free: worker profiles, job posting, matching, manual shortlisting, interview planning, and WhatsApp drafts.</p><p>Paid automation: team workflows, interview reminders, bulk outreach with consent, hiring analytics, and ATS exports.</p><p>Pricing will be validated with Malaysian employers. No billing is connected.</p>`);return}if(a==='deleteprofile'){if(!state.worker)return toast('No worker profile to delete.');state.people=state.people.filter(p=>p.id!==state.worker.id);state.shortlist=state.shortlist.filter(i=>i!==state.worker.id);state.interviews=state.interviews.filter(i=>i.person!==state.worker.id);state.worker=null;persist();render();toast('Your local worker profile was deleted.');return}if(a==='removejob'){state.jobs=state.jobs.filter(j=>j.id!==+id);if(!state.jobs.length){state.jobs=structuredClone(seed.jobs);toast('Last demo job removed; sample roles restored for matching.');}persist();render();return}if(a==='reset'){show('Reset this demo workspace?',`<p>This removes your locally added jobs, profiles, shortlists, and interviews and restores sample data.</p><div class="formactions"><button data-action="close">Cancel</button><button class="primary" data-action="confirmreset">Reset local data</button></div>`);return}if(a==='confirmreset'){state=structuredClone(seed);persist();$('#modal').close();render();toast('Demo workspace reset.');return}if(a==='export'){let url=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}));let a=document.createElement('a');a.href=url;a.download='industrial-workforce-demo.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}}
document.addEventListener('click',e=>{let b=e.target.closest('[data-action]');if(b)act(b.dataset.action,b.dataset.id)});document.addEventListener('change',e=>{if(e.target.id==='role'){role=e.target.value;view='overview';location.hash='overview';render()}if(e.target.id==='jobfilter'){selectedJob=+e.target.value;render()}if(e.target.id==='region'){region=e.target.value;render()}});document.addEventListener('input',e=>{if(e.target.id==='search'){let pos=e.target.selectionStart;query=e.target.value;render();$('#search').focus();$('#search').setSelectionRange(pos,pos)}});window.addEventListener('hashchange',()=>{view=location.hash.slice(1)||'overview';query='';render()});view=location.hash.slice(1)||'overview';render();
